class ActiveQueue<T> {
  private tail: Promise<unknown> = Promise.resolve();
  private items: T[] = [];
  put(item: T): Promise<number> {
    this.tail = this.tail.then(() => { this.items.push(item); });
    return this.tail.then(() => this.items.length);   // the future
  }
}
